struct TokenBucket {
    capacity: 100      // max tokens
    refillRate: 10      // 10 tokens/sec
    tokens: 50           // current tokens
    lastRefill: timestamp
}

function allowRequest(bucket): (allowed, remaining, retryAfter) {
    now = currentTime()
    elapsed = now - bucket.lastRefill
    tokensToAdd = elapsed * bucket.refillRate
    bucket.tokens = min(bucket.capacity, bucket.tokens + tokensToAdd)
    bucket.lastRefill = now

    if bucket.tokens >= 1 {
        bucket.tokens -= 1
        return (true, bucket.tokens, 0)
    }

    retryAfter = (1 - bucket.tokens) / bucket.refillRate
    return (false, 0, retryAfter)
}

struct SlidingWindow {
    windowSize: 60       // seconds
    maxRequests: 100
    prevCount: 80          // requests in previous window
    currCount: 20          // requests in current window
    currWindowStart: timestamp
}

function allowRequest(window): (allowed, remaining) {
    now = currentTime()
    elapsed = now - window.currWindowStart

    if elapsed >= window.windowSize {
        // Rotate window
        window.prevCount = window.currCount
        window.currCount = 0
        window.currWindowStart = now
        elapsed = 0
    }

    // Weighted count: prev window decays by elapsed fraction
    overlap = (window.windowSize - elapsed) / window.windowSize
    weightedCount = window.prevCount * overlap + window.currCount

    if weightedCount < window.maxRequests {
        window.currCount++
        return (true, window.maxRequests - weightedCount - 1)
    }

    return (false, 0)
}
